-- Short stored-program and DML variants without DELIMITER
CREATE TABLE audit_log (id INT AUTO_INCREMENT PRIMARY KEY, tbl VARCHAR(64), action ENUM('I','U','D'), at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE child (id INT PRIMARY KEY, pid INT, CONSTRAINT fk_p FOREIGN KEY (pid) REFERENCES parent(id) ON DELETE SET NULL);
CREATE TABLE ck (a INT, CONSTRAINT chk_a CHECK (a > 0), b INT CHECK (b < 100));
CREATE TABLE idx_t (a INT, b INT, c VARCHAR(100), INDEX ix_ab (a, b), INDEX ix_c (c(20)), UNIQUE KEY uq (a, c));
CREATE TABLE def_expr (id INT PRIMARY KEY, uuid CHAR(36) DEFAULT (UUID()), created DATETIME DEFAULT NOW());
CREATE TABLE inv (id INT, v INT INVISIBLE, KEY ((v + 1)));
CREATE TABLE cmt (id INT COMMENT 'the id', name VARCHAR(10) COMMENT 'nm') COMMENT='a table';
CREATE TABLE rowfmt (id INT) ENGINE=InnoDB ROW_FORMAT=DYNAMIC KEY_BLOCK_SIZE=8;
CREATE TABLE big (id INT) ENGINE=MyISAM DEFAULT CHARSET=latin1;
CREATE TABLE `select` (`from` INT, `where` INT);
CREATE TABLE ts (a TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6));
CREATE TABLE sp (id INT, g GEOMETRY NOT NULL SRID 4326, SPATIAL INDEX(g));
CREATE TABLE ch (a CHAR(3) CHARACTER SET ascii COLLATE ascii_bin, b TEXT CHARSET utf8mb4);
CREATE TABLE ai (id INT UNSIGNED NOT NULL AUTO_INCREMENT, PRIMARY KEY (id)) AUTO_INCREMENT=100;
CREATE TABLE decs (a DECIMAL, b DECIMAL(5), c NUMERIC(8,2), d DEC(4,1), e FIXED(3,1), f REAL, g DOUBLE PRECISION, h BOOL, i BOOLEAN, j INTEGER, k INT(11));
ALTER TABLE t ADD PRIMARY KEY (id);
ALTER TABLE t DROP PRIMARY KEY;
ALTER TABLE t ADD COLUMN c INT NOT NULL DEFAULT 0 COMMENT 'x', ALGORITHM=INPLACE, LOCK=NONE;
ALTER TABLE t ADD PARTITION (PARTITION p3 VALUES LESS THAN (2030));
ALTER TABLE t RENAME COLUMN a TO b;
ALTER TABLE t RENAME INDEX i1 TO i2;
ALTER TABLE t DROP CHECK chk_a;
ALTER TABLE t ADD CONSTRAINT uq UNIQUE (a, b);
ALTER TABLE t DISABLE KEYS;
ALTER TABLE t COMMENT = 'new comment';
ALTER TABLE t DEFAULT CHARSET=utf8mb4;
ALTER TABLE t MODIFY a INT NOT NULL AFTER b;
ALTER DATABASE app CHARACTER SET utf8mb4;
DROP INDEX `PRIMARY` ON t;
DROP TRIGGER IF EXISTS trg_bi;
DROP PROCEDURE IF EXISTS sp_x;
DROP FUNCTION IF EXISTS f_x;
DROP EVENT IF EXISTS ev_purge;
CREATE TABLE IF NOT EXISTS x LIKE y;
CREATE SCHEMA IF NOT EXISTS s;
XA START 'a';
